class SemVer : IComparable<SemVer>
public int CompareTo(SemVer? other)
{
    if (other is null) return 1;
    if (Major != other.Major) return Major.CompareTo(other.Major);
    ... same for Minor, then return Patch.CompareTo(other.Patch);
}

